describe('Lazy-loaded components smooth appearance without layout shift', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport(1280, 720);
  });

  it('should load lazy components smoothly without layout shift on scroll', () => {
    // Get initial scroll position and viewport dimensions
    cy.window().then((win) => {
      const initialHeight = win.document.documentElement.scrollHeight;

      // Verify lazy-loaded image container exists but is not yet loaded
      cy.get('[data-testid="lazy-image-container"]').should('exist');
      cy.get('[data-testid="lazy-image"]').should('have.attr', 'loading', 'lazy');

      // Scroll to trigger lazy loading
      cy.get('[data-testid="lazy-image"]').scrollIntoView();

      // Wait for image to load
      cy.get('[data-testid="lazy-image"]').should('have.css', 'opacity', '1');

      // Verify no layout shift occurred by checking scroll height remains stable
      cy.window().then((win2) => {
        const finalHeight = win2.document.documentElement.scrollHeight;
        // Allow minimal variance (5px) for browser rendering differences
        expect(Math.abs(finalHeight - initialHeight)).to.be.lessThan(5);
      });

      // Verify image is fully visible and rendered
      cy.get('[data-testid="lazy-image"]').should('be.visible');
      cy.get('[data-testid="lazy-image"]').should('have.attr', 'src').and('not.be.empty');
    });
  });

  it('should handle multiple lazy-loaded components without cumulative layout shift', () => {
    // Get initial layout metrics
    cy.window().then((win) => {
      const initialScrollHeight = win.document.documentElement.scrollHeight;
      const initialClientHeight = win.innerHeight;

      // Verify multiple lazy containers exist
      cy.get('[data-testid="lazy-component"]').should('have.length.greaterThan', 1);

      // Scroll through multiple lazy components
      cy.get('[data-testid="lazy-component"]').each(($component, index) => {
        cy.wrap($component).scrollIntoView();

        // Wait for component content to load
        cy.wrap($component).find('[data-testid="lazy-content"]').should('have.css', 'opacity', '1');

        // Verify component maintains its dimensions
        cy.wrap($component).should('have.css', 'min-height').and('not.equal', '0px');
      });

      // Verify final scroll height is stable (no cumulative shift)
      cy.window().then((win2) => {
        const finalScrollHeight = win2.document.documentElement.scrollHeight;
        const heightDifference = Math.abs(finalScrollHeight - initialScrollHeight);
        expect(heightDifference).to.be.lessThan(10);
      });
    });
  });

  it('should maintain layout stability when lazy component fails to load', () => {
    // Simulate network error for one lazy component
    cy.intercept('GET', '**/lazy-image-*.jpg', { statusCode: 404 }).as('failedImage');

    cy.get('[data-testid="lazy-image-error"]').scrollIntoView();
    cy.wait('@failedImage');

    // Verify placeholder or fallback is displayed
    cy.get('[data-testid="lazy-image-error"]').parent().should('have.css', 'min-height').and('not.equal', '0px');

    // Verify error state doesn't cause layout shift
    cy.get('[data-testid="lazy-image-error"]').parent().should('have.class', 'loaded-error');

    // Verify page remains scrollable and stable
    cy.window().then((win) => {
      expect(win.document.documentElement.scrollHeight).to.be.greaterThan(0);
    });
  });

  it('should apply smooth transitions when lazy content becomes visible', () => {
    cy.get('[data-testid="lazy-component-with-transition"]').should('exist');

    // Verify transition CSS is applied
    cy.get('[data-testid="lazy-component-with-transition"]').should('have.css', 'transition').and('include', 'opacity');

    // Scroll component into view
    cy.get('[data-testid="lazy-component-with-transition"]').scrollIntoView();

    // Verify opacity animates from 0 to 1
    cy.get('[data-testid="lazy-component-with-transition"]').should('have.css', 'opacity', '1');

    // Verify no transform or position changes during transition
    cy.get('[data-testid="lazy-component-with-transition"]').should('have.css', 'transform', 'none');
  });
});
